pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testRegression_property() public {
        vm.warp(100);
        vm.roll(15);
        address actor = address(0x1234);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool success, ) = address(c).call{value: 10 ether}("");
        require(success, "call failed");
        uint256 balanceAfter = address(c).balance;
        assertEq(balanceAfter, 0);
    }
}
